+    exit 1
+else
+    echo "SUCCESS: All GetIFPresent references changed to GetIfPresent"
+fi
+
+# Check that new method names exist
+if ! grep -r "GetAll" . --include="*.go" > /dev/null; then
+    echo "ERROR: No GetAll references found"
+    exit 1
+else
+    echo "SUCCESS: GetAll references found"
+fi
+
+if ! grep -r "GetIfPresent" . --include="*.go" > /dev/null; then
+    echo "ERROR: No GetIfPresent references found"
+    exit 1
+else
+    echo "SUCCESS: GetIfPresent references found"
+fi
+
+echo "All checks passed!"

